import { usageError } from './errors.js'

const NAME = /^[A-Za-z0-9_.-]+$/
const COST = /^[0-9]+$/

/**
 * Split the input into directives. A trailing newline leaves an empty tail
 * that is not a line of its own.
 */
export function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function checkName(name, lineNumber) {
  if (!NAME.test(name)) {
    throw usageError(`error: line ${lineNumber}: invalid task name ${name}`)
  }
}

/**
 * Parse the input text into a graph: a map from task name to its cost and the
 * set of names it depends on. Every failure is reported in input order.
 */
export function parseGraph(text) {
  const costs = new Map()
  const deps = new Map()
  /** Dependency names in the order the input mentions them. */
  const mentioned = []

  const lines = splitLines(text)
  for (let index = 0; index < lines.length; index += 1) {
    const lineNumber = index + 1
    const line = lines[index].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw usageError(`error: line ${lineNumber}: expected task <name> <cost>`)
      }
      const [, name, cost] = words
      checkName(name, lineNumber)
      if (!COST.test(cost)) {
        throw usageError(`error: line ${lineNumber}: cost must be a non-negative integer`)
      }
      if (costs.has(name)) {
        throw usageError(`error: line ${lineNumber}: task ${name} is declared twice`)
      }
      costs.set(name, Number(cost))
      if (!deps.has(name)) deps.set(name, new Set())
      continue
    }

    if (directive === 'dep') {
      if (words.length < 3) {
        throw usageError(`error: line ${lineNumber}: expected dep <name> <dependency>...`)
      }
      for (let at = 1; at < words.length; at += 1) checkName(words[at], lineNumber)
      const name = words[1]
      if (!deps.has(name)) deps.set(name, new Set())
      mentioned.push(name)
      for (let at = 2; at < words.length; at += 1) {
        mentioned.push(words[at])
        deps.get(name).add(words[at])
      }
      continue
    }

    throw usageError(`error: line ${lineNumber}: unknown directive ${directive}`)
  }

  for (const name of mentioned) {
    if (!costs.has(name)) throw usageError(`error: unknown task ${name}`)
  }

  const tasks = new Map()
  for (const name of [...costs.keys()].sort(compareNames)) {
    tasks.set(name, { name, cost: costs.get(name), deps: [...deps.get(name)].sort(compareNames) })
  }
  return tasks
}

/** Ascending name order. */
export function compareNames(left, right) {
  if (left < right) return -1
  if (left > right) return 1
  return 0
}
"}

