{"file_path":"src/graph.js","content":"/** Analysing a parsed build graph: cycles, waves, times and priorities. */

import { cycleError } from './errors.js'
import { compareNames } from './parse.js'

/**
 * Report the first cycle a depth-first search finds, starting from each task in
 * ascending name order and walking each task's dependencies in ascending name
 * order. Returns when the graph is acyclic.
 */
export function checkAcyclic(tasks) {
  const WHITE = 0
  const GRAY = 1
  const BLACK = 2
  const colour = new Map()
  for (const name of tasks.keys()) colour.set(name, WHITE)

  for (const root of tasks.keys()) {
    if (colour.get(root) !== WHITE) continue
    const frames = [{ name: root, at: 0 }]
    colour.set(root, GRAY)
    while (frames.length > 0) {
      const frame = frames[frames.length - 1]
      const deps = tasks.get(frame.name).deps
      if (frame.at < deps.length) {
        const next = deps[frame.at]
        frame.at += 1
        if (colour.get(next) === GRAY) {
          const start = frames.findIndex((held) => held.name === next)
          const names = frames.slice(start).map((held) => held.name)
          names.push(next)
          throw cycleError(`error: cycle: ${names.join(' -> ')}`)
        }
        if (colour.get(next) === WHITE) {
          colour.set(next, GRAY)
          frames.push({ name: next, at: 0 })
        }
      } else {
        colour.set(frame.name, BLACK)
        frames.pop()
      }
    }
  }
}

/** Tasks in an order where every task follows all of its dependencies. */
function topologicalOrder(tasks) {
  const order = []
  const done = new Set()
  for (const root of tasks.keys()) {
    if (done.has(root)) continue
    const frames = [{ name: root, at: 0 }]
    while (frames.length > 0) {
      const frame = frames[frames.length - 1]
      const deps = tasks.get(frame.name).deps
      if (frame.at < deps.length) {
        const next = deps[frame.at]
        frame.at += 1
        if (!done.has(next)) frames.push({ name: next, at: 0 })
      } else {
        if (!done.has(frame.name)) {
          done.add(frame.name)
          order.push(frame.name)
        }
        frames.pop()
      }
    }
  }
  return order
}

/**
 * The start, finish and wave depth of every task, with unlimited workers, plus
 * the makespan that follows.
 */
export function analyse(tasks) {
  const order = topologicalOrder(tasks)
  const report = new Map()
  let total = 0
  for (const name of order) {
    const task = tasks.get(name)
    let start = 0
    let depth = 0
    for (const dep of task.deps) {
      const held = report.get(dep)
      if (held.finish > start) start = held.finish
      if (held.depth + 1 > depth) depth = held.depth + 1
    }
    const finish = start + task.cost
    report.set(name, { name, start, finish, depth })
    if (finish > total) total = finish
  }
  return { report, total, order }
}

/** The waves, as arrays of names in ascending order indexed by depth. */
export function waves(tasks) {
  const { report, total } = analyse(tasks)
  const grouped = []
  for (const name of [...tasks.keys()].sort(compareNames)) {
    const depth = report.get(name).depth
    while (grouped.length <= depth) grouped.push([])
    grouped[depth].push(name)
  }
  return { grouped, total }
}

/**
 * The priority of every task: the cost of the longest chain that begins at it,
 * counting its own cost and then the costs down to any task nothing depends on.
 */
export function priorities(tasks) {
  const order = topologicalOrder(tasks)
  const priority = new Map()
  for (const name of tasks.keys()) priority.set(name, tasks.get(name).cost)
  for (let at = order.length - 1; at >= 0; at -= 1) {
    const name = order[at]
    const mine = priority.get(name)
    for (const dep of tasks.get(name).deps) {
      const through = mine + tasks.get(dep).cost
      if (through > priority.get(dep)) priority.set(dep, through)
    }
  }
  return priority
}
"}

