import { compareNames } from './parse.js'
import { priorities } from './graph.js'

/**
 * Run the list scheduler: at each instant, while a worker is free and a task is
 * ready, start the ready task of greatest priority, ties broken by ascending
 * name, on the free worker of smallest index.
 */
export function pack(tasks, workerCount) {
  const priority = priorities(tasks)
  const names = [...tasks.keys()].sort(compareNames)
  const free = new Array(workerCount).fill(0)
  const runs = []
  for (let at = 0; at < workerCount; at += 1) runs.push([])

  const finish = new Map()
  const started = new Set()
  let now = 0
  let makespan = 0
  let remaining = names.length

  while (remaining > 0) {
    for (;;) {
      const worker = free.findIndex((when) => when <= now)
      if (worker === -1) break
      let chosen = null
      for (const name of names) {
        if (started.has(name)) continue
        let ready = true
        for (const dep of tasks.get(name).deps) {
          if (!finish.has(dep) || finish.get(dep) > now) {
            ready = false
            break
          }
        }
        if (!ready) continue
        if (chosen === null || priority.get(name) > priority.get(chosen)) chosen = name
      }
      if (chosen === null) break
      const ends = now + tasks.get(chosen).cost
      started.add(chosen)
      finish.set(chosen, ends)
      free[worker] = ends
      runs[worker].push({ name: chosen, start: now, finish: ends })
      remaining -= 1
      if (ends > makespan) makespan = ends
    }
    if (remaining === 0) break
    let next = null
    for (const when of free) {
      if (when > now && (next === null || when < next)) next = when
    }
    if (next === null) break
    now = next
  }

  return { runs, makespan }
}
"}

