/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { AppError, usageError } from './errors.js'
import { parseGraph, compareNames } from './parse.js'
import { analyse, checkAcyclic, waves } from './graph.js'
import { pack } from './schedule.js'

const WORKERS = /^[1-9][0-9]*$/

/** The mode and worker count the arguments ask for. */
function readArguments(argv) {
  const usage = usageError('error: usage: cli.js waves|explain|pack <workers>')
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0], workers: 0 }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS.test(argv[1])) throw usageError('error: workers must be a positive integer')
    return { mode: 'pack', workers: Number(argv[1]) }
  }
  throw usage
}

function readStandardInput() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

/** The lines the chosen mode prints for the given graph. */
function report(tasks, mode, workers) {
  const lines = []
  if (mode === 'waves') {
    const { grouped, total } = waves(tasks)
    for (let at = 0; at < grouped.length; at += 1) lines.push(`wave ${at}: ${grouped[at].join(' ')}`)
    lines.push(`total ${total}`)
    return lines
  }
  if (mode === 'explain') {
    const { report: times, total } = analyse(tasks)
    for (const name of [...tasks.keys()].sort(compareNames)) {
      const held = times.get(name)
      lines.push(`${name} start=${held.start} finish=${held.finish} depth=${held.depth}`)
    }
    lines.push(`total ${total}`)
    return lines
  }
  const { runs, makespan } = pack(tasks, workers)
  for (let at = 0; at < runs.length; at += 1) {
    const ran = runs[at].map((run) => ` ${run.name}@${run.start}-${run.finish}`).join('')
    lines.push(`worker ${at}:${ran}`)
  }
  lines.push(`makespan ${makespan}`)
  return lines
}

function main() {
  const { mode, workers } = readArguments(process.argv.slice(2))
  const tasks = parseGraph(readStandardInput())
  checkAcyclic(tasks)
  process.stdout.write(report(tasks, mode, workers).map((line) => `${line}\n`).join(''))
}

try {
  main()
} catch (error) {
  if (error instanceof AppError) {
    process.stderr.write(`${error.message}\n`)
    process.exit(error.code)
  }
  throw error
}
"}

